// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _test(address a, address b, uint256 v1, uint256 v2) internal {
        v1 = bound(v1, 0, 1000000000000000000000000000000);
        v2 = bound(v2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a != b);
        vm.assume(v1 > 0 && v2 > 0);
        vm.assume(a.balance == 0 && b.balance == 0);
        uint256 preBal = address(c).balance;
        try c.deposit{value: v1}() {} catch { return; }
        try c.deposit{value: v2}() {} catch { return; }
        try c.refund() {} catch { return; }
        assertTrue(address(c).balance == preBal + v1 + v2 - v1 - v2);
    }

    function testFuzz_test(address a, address b, uint256 v1, uint256 v2) public {
        _test(a, b, v1, v2);
    }

    receive() external payable {}
}
